local Base = require("Character/BigWorld/XEcologyConstructAI/XEcologyConstructAIBase")
local BaseState = require("Character/BigWorld/XEcologyConstructAI/XEcologyConstructAIBaseState")
local FindPathState = require("Character/BigWorld/XEcologyConstructAI/XEcologyFindCombinePathState")

--region 阿尔法生态2.0期静态参数
---生态状态枚举
local StateEnum = {
    None = 0,
    ---全息状态
    Holographic= 1,
}
---数据黑板key值
local DataBoardKey = {
    None = 0,
    ---全息状态
    Holographic= 1,
}
